     &Methods;








   &reftitle.examples;

    Waiting for a stream to become readable


<?php
use Io\Poll\Context;
use Io\Poll\Event;
use Time\Duration;

[$reader, $writer] = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, STREAM_IPPROTO_IP);

$context = new Context();
$context->add(new StreamPollHandle($reader), [Event::Read], 'reader');

// Nothing can be read yet, so the wait times out.
var_dump(count($context->wait(Duration::fromMilliseconds(10))));

fwrite($writer, 'ping');

foreach ($context->wait(Duration::fromSeconds(1)) as $watcher) {
    $stream = $watcher->getHandle()->getStream();
    echo $watcher->getData(), ': ', fread($stream, 1024), PHP_EOL;
}


